import json
for lang,m in D.items():
    p=f'src/i18n/dict/{lang}.ts';s=open(p).read()
    add=''.join(f'  {json.dumps(k,ensure_ascii=False)}: {json.dumps(v,ensure_ascii=False)},\n' for k,v in m.items() if json.dumps(k,ensure_ascii=False)+':' not in s)
    i=s.rindex('};');s=s[:i]+add+s[i:];open(p,'w').write(s);print(lang,add.count('\n'))
